insert into public.blog_posts(slug,title,body,data,published) values('a-taste-of-bihu','Bihu, and the sweetness of coming home.','In Assam, Bihu brings people together around food, music and the simple pleasure of a shared table. Pitha and laru are familiar companions to these celebrations, with recipes that differ from home to home.
insert into public.blog_posts(slug,title,body,data,published) values('the-art-of-slow','Good things take their own sweet time.','Some flavours cannot be hurried. Milk thickens slowly. Sugar changes with heat. A careful hand knows when a mixture is ready to leave the pan.
insert into public.blog_posts(slug,title,body,data,published) values('a-thoughtful-gift','A little thought goes a long way.','The best gift starts with the person receiving it. Are they always reaching for the last kaju katli? Do they prefer coconut and jaggery? A small assortment of their favourites says you have been paying attention.
